begin;
create extension if not exists pgtap with schema extensions;
create temp table invite_results(result text);
create temp table invite_ids(key text primary key,id uuid);
grant select,insert on invite_results,invite_ids to authenticated,anon;
set local role authenticated;
select set_config('request.jwt.claims','{"sub":"ae700000-0000-4000-8000-000000000002","role":"authenticated"}',true);
select set_config('request.jwt.claims','{"sub":"ae700000-0000-4000-8000-000000000001","role":"authenticated"}',true);
reset role;
update public.business_modules set enabled=true where business_id=(select id from invite_ids where key='a') and module='management';
create temp table before_config as select to_jsonb(s) data from public.business_settings s where business_id=(select id from invite_ids where key='a');
create temp table before_modules as select jsonb_agg(to_jsonb(m) order by module) data from public.business_modules m where business_id=(select id from invite_ids where key='a');
set local role authenticated;
select set_config('request.jwt.claims','{"sub":"ae700000-0000-4000-8000-000000000001","role":"authenticated"}',true);
reset role;
set local role anon;
select set_config('request.jwt.claims','{"role":"anon"}',true);
set local role authenticated;
select set_config('request.jwt.claims','{"sub":"ae700000-0000-4000-8000-000000000002","role":"authenticated"}',true);
select set_config('request.jwt.claims','{"sub":"ae700000-0000-4000-8000-000000000001","role":"authenticated"}',true);
select public.generate_platform_business_invite((select id from invite_ids where key='a'),repeat('b',64));
select public.revoke_platform_business_invite((select id from invite_ids where key='a'));
select public.generate_platform_business_invite((select id from invite_ids where key='a'),repeat('c',64));
reset role;
update public.business_invites set created_at=now()-interval '8 days',expires_at=now()-interval '1 day' where token_hash=repeat('c',64);
set local role authenticated;
select set_config('request.jwt.claims','{"sub":"ae700000-0000-4000-8000-000000000002","role":"authenticated"}',true);
select set_config('request.jwt.claims','{"sub":"ae700000-0000-4000-8000-000000000001","role":"authenticated"}',true);
select public.generate_platform_business_invite((select id from invite_ids where key='a'),repeat('d',64));
select public.generate_platform_business_invite((select id from invite_ids where key='b'),repeat('e',64));
select public.generate_platform_business_invite((select id from invite_ids where key='rollback'),repeat('f',64));
select set_config('request.jwt.claims','{"sub":"ae700000-0000-4000-8000-000000000002","role":"authenticated"}',true);
select set_config('request.jwt.claims','{"sub":"ae700000-0000-4000-8000-000000000003","role":"authenticated"}',true);
reset role;
-- Force failure after membership insertion: both writes must roll back.
create function pg_temp.fail_invite_accept() returns trigger language plpgsql as $$ begin if new.token_hash=repeat('f',64) and new.status='accepted' then raise exception 'test_rollback'; end if; return new; end $$;
create trigger test_invite_failure before update on public.business_invites for each row execute function pg_temp.fail_invite_accept();
set local role authenticated;
select set_config('request.jwt.claims','{"sub":"ae700000-0000-4000-8000-000000000005","role":"authenticated"}',true);
reset role;
set local role authenticated;
select set_config('request.jwt.claims','{"sub":"ae700000-0000-4000-8000-000000000003","role":"authenticated"}',true);
select set_config('request.jwt.claims','{"sub":"ae700000-0000-4000-8000-000000000001","role":"authenticated"}',true);
select result from invite_results;
rollback;
